const std = @import("std");
const h = @import("heap.zig");
fn copy(heap: *h.Heap, record: *h.Collection, copied: []bool, queue: *std.ArrayList(usize), id: usize) void {
    if (id == 0 or copied[id - 1]) return;
    const object = heap.object(id);
    copied[id - 1] = true;
    object.address = heap.top;
    heap.top += object.size();
    object.moves += 1;
    record.live.add(object.size());
    record.moved.add(object.size());
    h.append(usize, queue, id);
}
pub fn collect(heap: *h.Heap, record: *h.Collection) void {
    heap.base = heap.size / 2 - heap.base;
    heap.top = heap.base;
    const copied = h.alloc(bool, heap.objects.items.len);
    @memset(copied, false);
    var queue: std.ArrayList(usize) = .empty;
    record.work += h.n(heap.roots.items.len);
    for (heap.roots.items) |root| copy(heap, record, copied, &queue, root);
    var front: usize = 0;
    while (front < queue.items.len) : (front += 1) {
        const object = heap.get(queue.items[front]);
        record.work += h.n(object.size() + object.p);
        for (object.fields) |value| copy(heap, record, copied, &queue, value);
    }
    for (heap.objects.items, copied) |*object, done| if (object.present and !done) {
        object.present = false;
        record.freed.add(object.size());
    };
}

const std = @import("std");
const h = @import("heap.zig");
const mark = @import("mark_sweep.zig");
pub fn barrier(heap: *h.Heap, target: usize, value: usize) void {
    if (heap.get(target).address < heap.collector.young) return;
    heap.barriers += 1;
    if (value != 0 and heap.get(value).address < heap.collector.young and !heap.remembered[target - 1]) {
        heap.remembered[target - 1] = true;
        heap.remembers += 1;
    }
}
const Evacuation = struct {
    heap: *h.Heap,
    record: *h.Collection,
    pending: []bool,
    top: usize,
    tenure: bool,
    major: bool,
    queue: std.ArrayList(usize) = .empty,
    fn evacuate(self: *Evacuation, id: usize) bool {
        if (id == 0 or !self.pending[id - 1]) return true;
        self.pending[id - 1] = false;
        const object = self.heap.object(id);
        object.age += 1;
        object.moves += 1;
        if (self.tenure or object.age >= self.heap.collector.promotion_age) {
            const address = h.firstFit(self.heap, object.size(), self.heap.collector.young, self.heap.size) orelse return false;
            object.address = address;
            self.record.promoted.add(object.size());
        } else {
            object.address = self.top;
            self.top += object.size();
        }
        self.record.moved.add(object.size());
        if (!self.major) self.record.live.add(object.size());
        h.append(usize, &self.queue, id);
        return true;
    }
};
pub fn collect(heap: *h.Heap, record: *h.Collection) bool {
    const major = h.eq(record.kind, "major") or h.eq(record.kind, "full");
    const tenure = h.eq(record.kind, "tenure") or h.eq(record.kind, "full");
    if (major) {
        mark.mark(heap, record);
        mark.sweep(heap, record, true);
    }
    const pending = h.alloc(bool, heap.objects.items.len);
    for (heap.objects.items, pending) |object, *value| value.* = object.present and object.address < heap.collector.young;
    const destination = heap.collector.young / 2 - heap.base;
    var state: Evacuation = .{ .heap = heap, .record = record, .pending = pending, .top = destination,
         .major = major, .tenure = tenure };
    record.work += h.n(heap.roots.items.len);
    for (heap.roots.items) |root| if (!state.evacuate(root)) return false;
    for (h.addressOrder(heap)) |id| if (heap.remembered[id - 1]) {
        const object = heap.get(id);
        record.work += h.n(1 + object.p);
        for (object.fields) |value| if (!state.evacuate(value)) return false;
    };
    var front: usize = 0;
    while (front < state.queue.items.len) : (front += 1) {
        const object = heap.get(state.queue.items[front]);
        record.work += h.n(object.size() + object.p);
        for (object.fields) |value| if (!state.evacuate(value)) return false;
    }
    for (heap.objects.items, pending) |*object, remains| if (remains) {
        object.present = false;
        record.freed.add(object.size());
    };
    heap.base = destination;
    heap.top = state.top;
    @memset(&heap.remembered, false);
    for (heap.objects.items) |object| if (object.present and object.address >= heap.collector.young) {
        for (object.fields) |value| if (value != 0 and heap.get(value).address < heap.collector.young) {
            heap.remembered[object.id - 1] = true;
            break;
        };
    };
    return true;
}

const std = @import("std");
pub var allocator: std.mem.Allocator = undefined;
pub fn alloc(comptime T: type, count: usize) []T {
    return allocator.alloc(T, count) catch @panic("allocation failed");
}
pub fn create(comptime T: type, value: T) *T {
    const result = allocator.create(T) catch @panic("allocation failed");
    result.* = value;
    return result;
}
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void {
    list.append(allocator, value) catch @panic("allocation failed");
}
pub fn fmt(comptime pattern: []const u8, args: anytype) []const u8 {
    return std.fmt.allocPrint(allocator, pattern, args) catch @panic("allocation failed");
}
pub fn n(value: anytype) i64 {
    return @intCast(value);
}
pub fn u(value: i64) usize {
    return @intCast(value);
}
pub fn number(text: []const u8) i64 {
    return std.fmt.parseInt(i64, text, 10) catch unreachable;
}
pub fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
pub fn split(text: []const u8, delimiter: u8) []const []const u8 {
    var result: std.ArrayList([]const u8) = .empty;
    var fields = std.mem.splitScalar(u8, text, delimiter);
    while (fields.next()) |field| append([]const u8, &result, field);
    return result.items;
}
pub const Text = struct {
    data: std.ArrayList(u8) = .empty,
    pub fn add(self: *Text, comptime pattern: []const u8, args: anytype) void {
        self.data.appendSlice(allocator, fmt(pattern, args)) catch @panic("allocation failed");
    }
    pub fn value(self: Text) []const u8 {
        return self.data.items;
    }
};
pub const Lines = struct {
    data: std.ArrayList([]const u8) = .empty,
    pub fn add(self: *Lines, comptime pattern: []const u8, args: anytype) void {
        append([]const u8, &self.data, fmt(pattern, args));
    }
    pub fn extend(self: *Lines, other: Lines) void {
        for (other.data.items) |line| self.add("{s}", .{line});
    }
    pub fn blank(self: *Lines) void {
        self.add("", .{});
    }
};
pub fn readLines(io: std.Io, name: []const u8) ![]const []const u8 {
    const text = try std.Io.Dir.cwd().readFileAlloc(io, fmt("input/{s}", .{name}), allocator, .unlimited);
    const lines = split(text, '\n');
    return lines[0 .. lines.len - 1];
}
pub fn writeLines(io: std.Io, name: []const u8, lines: Lines) !void {
    var text: Text = .{};
    for (lines.data.items) |line| text.add("{s}\n", .{line});
    try std.Io.Dir.cwd().createDirPath(io, "output");
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = fmt("output/{s}", .{name}), .data = text.value() });
}
pub const CollectorType = enum { MARK_SWEEP, MARK_COMPACT, COPYING, GENERATIONAL, REFCOUNT };
pub const Collector = struct { name: []const u8, kind: CollectorType, young: usize = 0, promotion_age: usize = 0 };
pub const Pair = struct {
    count: i64 = 0,
    words: i64 = 0,
    pub fn add(self: *Pair, size: usize) void {
        self.count += 1;
        self.words += n(size);
    }
    pub fn merge(self: *Pair, other: Pair) void {
        self.count += other.count;
        self.words += other.words;
    }
    pub fn text(self: Pair) []const u8 {
        return fmt("{d} {d}", .{ self.count, self.words });
    }
};
pub const Object = struct {
    id: usize,
    p: usize,
    d: usize,
    fields: []usize,
    address: usize = 0,
    age: usize = 0,
    moves: usize = 0,
    references: i64 = 0,
    present: bool = true,
    marked: bool = false,
    pub fn size(self: Object) usize {
        return 1 + self.p + self.d;
    }
    pub fn init(id: usize, p: usize, data: usize, address: usize) Object {
        const fields = alloc(usize, p);
        @memset(fields, 0);
        return .{ .id = id, .p = p, .d = data, .fields = fields, .address = address };
    }
};
pub const Collection = struct { number: usize, line: usize, request: usize, kind: []const u8, live: Pair = .{},
     freed: Pair = .{}, moved: Pair = .{}, promoted: Pair = .{}, stack: usize = 0, work: i64 = 0,
     before: [2]i64 = .{ 0, 0 }, after: [2]i64 = .{ 0, 0 } };
pub const Heap = struct {
    size: usize,
    collector: Collector,
    base: usize = 0,
    top: usize = 0,
    objects: std.ArrayList(Object) = .empty,
    roots: std.ArrayList(usize) = .empty,
    remembered: [5000]bool = @splat(false),
    barriers: i64 = 0,
    remembers: i64 = 0,
    pub fn object(self: *Heap, id: usize) *Object {
        return &self.objects.items[id - 1];
    }
    pub fn get(self: *const Heap, id: usize) Object {
        return self.objects.items[id - 1];
    }
};
fn addressLess(heap: *const Heap, a: usize, b: usize) bool {
    return heap.get(a).address < heap.get(b).address;
}
pub fn addressOrder(heap: *const Heap) []usize {
    var ids: std.ArrayList(usize) = .empty;
    for (heap.objects.items) |object| if (object.present) append(usize, &ids, object.id);
    std.mem.sort(usize, ids.items, heap, addressLess);
    return ids.items;
}
pub const Block = struct { address: usize, length: usize };
pub fn rangeBlocks(heap: *const Heap, first: usize, end: usize) []Block {
    var result: std.ArrayList(Block) = .empty;
    var cursor = first;
    for (addressOrder(heap)) |id| {
        const object = heap.get(id);
        if (object.address < first or object.address >= end) continue;
        if (object.address > cursor) append(Block, &result, .{ .address = cursor, .length = object.address - cursor });
        cursor = object.address + object.size();
    }
    if (cursor < end) append(Block, &result, .{ .address = cursor, .length = end - cursor });
    return result.items;
}
pub fn freeBlocks(heap: *const Heap) []Block {
    var result: std.ArrayList(Block) = .empty;
    switch (heap.collector.kind) {
        .MARK_SWEEP, .REFCOUNT => return rangeBlocks(heap, 0, heap.size),
        .MARK_COMPACT, .COPYING => {
            const end = if (heap.collector.kind == .COPYING) heap.base + heap.size / 2 else heap.size;
            if (heap.top < end) append(Block, &result, .{ .address = heap.top, .length = end - heap.top });
        },
        .GENERATIONAL => {
            const end = heap.base + heap.collector.young / 2;
            if (heap.top < end) append(Block, &result, .{ .address = heap.top, .length = end - heap.top });
            for (rangeBlocks(heap, heap.collector.young, heap.size)) |block| append(Block, &result, block);
        },
    }
    return result.items;
}
pub fn freeAmount(heap: *const Heap) [2]i64 {
    var result = [2]i64{ 0, 0 };
    for (freeBlocks(heap)) |block| {
        result[0] += n(block.length);
        result[1] = @max(result[1], n(block.length));
    }
    return result;
}
pub fn firstFit(heap: *const Heap, size: usize, first: usize, end: usize) ?usize {
    for (rangeBlocks(heap, first, end)) |block| if (block.length >= size) return block.address;
    return null;
}
pub fn used(heap: *const Heap) i64 {
    var total: i64 = 0;
    for (heap.objects.items) |object| if (object.present) {
        total += n(object.size());
    };
    return total;
}
pub fn dec2(a: i64, b: i64) []const u8 {
    const value = @divTrunc(200 * a + b, 2 * b);
    return fmt("{d}.{d:0>2}", .{ @divTrunc(value, 100), @mod(value, 100) });
}
pub fn pct(a: i64, b: i64) []const u8 {
    return if (b == 0) "-" else dec2(100 * a, b);
}
pub fn classTable(sizes: []const usize) []const u8 {
    var counts: [5]usize = @splat(0);
    for (sizes) |size| counts[if (size == 1) 0 else if (size < 4) 1 else if (size < 8) 2 else if (size < 16) 3 else 4] += 1;
    return fmt("1:{d} 2-3:{d} 4-7:{d} 8-15:{d} 16+:{d}", .{ counts[0], counts[1], counts[2], counts[3], counts[4] });
}
pub fn heapMap(heap: *const Heap, reachable: []const bool) []const u8 {
    const map = alloc(u8, heap.size);
    @memset(map, '.');
    const half = if (heap.collector.kind == .COPYING) heap.size / 2 else if (heap.collector.kind == .GENERATIONAL) heap.collector.young / 2 else 0;
    if (half > 0) @memset(map[half - heap.base .. 2 * half - heap.base], '-');
    for (heap.objects.items, 0..) |object, index| if (object.present) {
        const live = reachable[index];
        map[object.address] = if (live) 'A' + @as(u8, @intCast(index % 26)) else '#';
        @memset(map[object.address + 1 .. object.address + object.size()], if (live) 'a' + @as(u8,
             @intCast(index % 26)) else '=');
    };
    return map;
}

const std = @import("std");
const h = @import("heap.zig");
const mutator = @import("mutator.zig");
const mark = @import("mark_sweep.zig");
const copying = @import("copying.zig");
const generational = @import("generational.zig");
fn reachable(heap: *const h.Heap) []bool {
    const marks = h.alloc(bool, heap.objects.items.len);
    @memset(marks, false);
    var stack: std.ArrayList(usize) = .empty;
    for (heap.roots.items) |root| if (root != 0 and !marks[root - 1]) {
        marks[root - 1] = true;
        h.append(usize, &stack, root);
    };
    while (stack.items.len > 0) {
        const id = stack.items[stack.items.len - 1];
        stack.items.len -= 1;
        for (heap.get(id).fields) |value| if (value != 0 and !marks[value - 1]) {
            marks[value - 1] = true;
            h.append(usize, &stack, value);
        };
    }
    return marks;
}
fn amount(heap: *const h.Heap, ids: []const bool) h.Pair {
    var pair: h.Pair = .{};
    for (heap.objects.items, ids) |object, included| if (included) pair.add(object.size());
    return pair;
}
fn slot(heap: *const h.Heap, index: i64) usize {
    return if (index < 0) 0 else heap.roots.items[h.u(index)];
}
fn executePlain(heap: *h.Heap, command: mutator.Command) void {
    const args = command.args;
    switch (command.kind) {
        .ALLOC => {
            const id = heap.objects.items.len + 1;
            h.append(h.Object, &heap.objects, h.Object.init(id, h.u(args[0]), h.u(args[1]), 0));
            h.append(usize, &heap.roots, id);
        },
        .PUSH => h.append(usize, &heap.roots, slot(heap, args[0])),
        .LOAD => h.append(usize, &heap.roots, heap.get(heap.roots.items[h.u(args[0])]).fields[h.u(args[1])]),
        .POP => heap.roots.items.len -= h.u(args[0]),
        .SET => heap.object(heap.roots.items[h.u(args[0])]).fields[h.u(args[1])] = slot(heap, args[2]),
        .OVERWRITE => heap.roots.items[h.u(args[0])] = slot(heap, args[1]),
        .CHECKPOINT => {},
    }
}
const Checkpoint = struct { label: []const u8, line: usize, roots: usize, live: h.Pair, allocated: h.Pair,
     phase: h.Pair, survivors: h.Pair };
const Reference = struct {
    heap: *h.Heap,
    commands: []const mutator.Command,
    errors: []const mutator.Command,
    death: []usize,
    lifetime: []i64,
    birth: []i64,
    checkpoints: []const Checkpoint,
    counts: [7]usize = @splat(0),
    allocated: h.Pair = .{},
    peak: h.Pair = .{},
    ending: h.Pair = .{},
    peak_line: usize = 0,
    line_count: usize,
    fn analyze(source: []const mutator.Command) Reference {
        var reference: Reference = .{ .heap = h.create(h.Heap, .{ .size = 0, .collector = .{ .name = "",
             .kind = .MARK_SWEEP } }), .commands = &.{}, .errors = &.{}, .death = h.alloc(usize, source.len),
             .lifetime = h.alloc(i64, source.len), .birth = h.alloc(i64, source.len), .checkpoints = &.{},
             .line_count = source.len };
        @memset(reference.death, 0);
        @memset(reference.lifetime, 0);
        var commands: std.ArrayList(mutator.Command) = .empty;
        var errors: std.ArrayList(mutator.Command) = .empty;
        var checkpoints: std.ArrayList(Checkpoint) = .empty;
        var phase_first: usize = 1;
        var phase: h.Pair = .{};
        const heap = reference.heap;
        for (source) |raw| {
            var command = raw;
            const roots = heap.roots.items.len;
            const kind = command.kind;
            const a = command.args;
            if (command.reason == null) {
                var invalid = ((kind == .ALLOC or kind == .PUSH or kind == .LOAD) and roots == 64) or (kind == .POP and a[0] > h.n(roots));
                if (kind == .LOAD or kind == .SET or kind == .OVERWRITE) invalid = invalid or a[0] >= h.n(roots);
                const r = if (kind == .PUSH) a[0] else if (kind == .SET) a[2] else if (kind == .OVERWRITE) a[1] else -1;
                if (r >= h.n(roots)) invalid = true;
                if (invalid) command.reason = "stack" else if ((kind == .LOAD or kind == .SET) and heap.roots.items[h.u(a[0])] == 0) command.reason = "null" else if ((kind == .LOAD or kind == .SET) and a[1] >= h.n(heap.get(heap.roots.items[h.u(a[0])]).p)) command.reason = "field" else if (kind == .CHECKPOINT) {
                    for (checkpoints.items) |checkpoint| if (h.eq(checkpoint.label, command.label)) {
                        command.reason = "duplicate";
                        break;
                    };
                }
            }
            if (command.reason != null) {
                h.append(mutator.Command, &errors, command);
                continue;
            }
            if (kind == .ALLOC) {
                command.object = heap.objects.items.len + 1;
                reference.birth[heap.objects.items.len] = reference.allocated.words;
                reference.allocated.add(h.u(1 + a[0] + a[1]));
                phase.add(h.u(1 + a[0] + a[1]));
            }
            if (kind == .CHECKPOINT) command.checkpoint = checkpoints.items.len;
            executePlain(heap, command);
            h.append(mutator.Command, &commands, command);
            reference.counts[@intFromEnum(kind)] += 1;
            const live = reachable(heap);
            reference.ending = amount(heap, live);
            for (heap.objects.items, live, 0..) |object, alive, index| if (reference.death[index] == 0 and !alive) {
                reference.death[index] = command.line;
                reference.lifetime[index] = reference.allocated.words - reference.birth[index] - h.n(object.size());
            };
            if (reference.ending.words > reference.peak.words) {
                reference.peak = reference.ending;
                reference.peak_line = command.line;
            }
            if (kind == .CHECKPOINT) {
                var survivors: h.Pair = .{};
                for (heap.objects.items, live) |object, alive| if (object.id >= phase_first and alive) survivors.add(object.size());
                h.append(Checkpoint, &checkpoints, .{ .label = command.label, .line = command.line,
                     .roots = heap.roots.items.len, .live = reference.ending, .allocated = reference.allocated,
                     .phase = phase, .survivors = survivors });
                phase = .{};
                phase_first = heap.objects.items.len + 1;
            }
        }
        reference.commands = commands.items;
        reference.errors = errors.items;
        reference.checkpoints = checkpoints.items;
        return reference;
    }
    fn report(self: *const Reference) h.Lines {
        var out: h.Lines = .{};
        out.add("script lines {d} valid {d} errors {d}", .{ self.line_count, self.commands.len, self.errors.len });
        for (self.errors) |command| out.add("error line {d} {s}", .{ command.line, command.reason.? });
        var commands: h.Text = .{};
        commands.add("commands", .{});
        for (self.counts, 0..) |count, index| commands.add(" {s} {d}", .{ @tagName(@as(mutator.Kind,
             @enumFromInt(index))), count });
        out.add("{s}", .{commands.value()});
        const sizes = h.alloc(usize, self.heap.objects.items.len);
        for (self.heap.objects.items, sizes) |object, *size| size.* = object.size();
        out.add("allocated objects {d} words {d} sizes {s}", .{ self.allocated.count, self.allocated.words,
             h.classTable(sizes) });
        out.add("peak_live objects {d} words {d} line {d}", .{ self.peak.count, self.peak.words, self.peak_line });
        out.add("end_live objects {d} words {d} stack {d}", .{ self.ending.count, self.ending.words, self.heap.roots.items.len });
        var lifetimes: [6]usize = @splat(0);
        for (self.heap.objects.items, 0..) |_, index| {
            const value = self.lifetime[index];
            lifetimes[if (self.death[index] == 0) 5 else if (value < 64) 0 else if (value < 256) 1 else if (value < 1024) 2 else if (value < 4096) 3 else 4] += 1;
        }
        out.add("lifetimes 0-63 {d} 64-255 {d} 256-1023 {d} 1024-4095 {d} 4096+ {d} live {d}", .{ lifetimes[0],
             lifetimes[1], lifetimes[2], lifetimes[3], lifetimes[4], lifetimes[5] });
        for (self.checkpoints) |checkpoint| out.add("checkpoint {s} line {d} stack {d} live {s} allocated {s} phase {s} survivors {s} survival {s}",
             .{ checkpoint.label, checkpoint.line, checkpoint.roots, checkpoint.live.text(), checkpoint.allocated.text(),
             checkpoint.phase.text(), checkpoint.survivors.text(), h.pct(checkpoint.survivors.words,
             checkpoint.phase.words) });
        return out;
    }
};
const Pause = struct { line: usize, work: i64, freed: h.Pair, collection: bool };
const PauseStats = struct { work: i64 = 0, freed: i64 = 0, maximum: i64 = 0, p50: []const u8 = "-", p90: []const u8 = "-" };
fn integerLess(_: void, a: i64, b: i64) bool {
    return a < b;
}
fn pauseStats(pauses: []const Pause) PauseStats {
    var result: PauseStats = .{};
    const values = h.alloc(i64, pauses.len);
    for (pauses, values) |pause, *value| {
        result.work += pause.work;
        result.freed += pause.freed.words;
        result.maximum = @max(result.maximum, pause.work);
        value.* = pause.work;
    }
    if (pauses.len > 0) {
        std.mem.sort(i64, values, {}, integerLess);
        result.p50 = h.fmt("{d}", .{values[(50 * values.len + 99) / 100 - 1]});
        result.p90 = h.fmt("{d}", .{values[(90 * values.len + 99) / 100 - 1]});
    }
    return result;
}
const Segment = struct { end: i64, mutator: i64, active: bool };
const Timeline = struct {
    segments: std.ArrayList(Segment) = .empty,
    total: i64 = 0,
    mutator_units: i64 = 0,
    fn add(self: *Timeline, active: bool, length: i64) void {
