        var context: Cycles = .{ .heap = self.heap, .garbage = garbage, .parent = h.alloc(usize, count),
             .index = h.alloc(i64, count), .low = h.alloc(i64, count), .active = h.alloc(bool, count),
             .cyclic = h.alloc(bool, count) };
