        out.add("totals collections {d} pauses {d} work {d} freed {d} pause p50 {s} p90 {s} max {d}",
             .{ self.collections.items.len, self.pauses.items.len, stats.work, stats.freed, stats.p50,
             stats.p90, stats.maximum });
