        utilization.add("utilization {s} mmu", .{h.pct(self.timeline.mutator_units, self.timeline.total)});
        for (self.config.windows) |width| utilization.add(" {d}:{s}", .{ width, self.timeline.mmu(width) });
        out.add("{s}", .{utilization.value()});
